# Generated by build.py from recipe.yml for recipe dns-point-a-client-at-a-test-zone. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/.surl/dns site
cat > site/.surl/dns/example.test.zone <<'EOF'
$ORIGIN example.test.
$TTL 300
@   IN SOA ns1.example.test. hostmaster.example.test. 1 3600 600 86400 300
@   IN NS  ns1.example.test.
api IN A   127.0.0.1
EOF
printf '%s\n' 'orders api: up' > site/status.txt
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory site --cert server.pem --key server.key --dns-transport https dns://127.0.0.1:8080/ http://127.0.0.1:8081/ &
sleep 1
curl -sS --doh-url https://127.0.0.1:8080/dns-query --cacert server.pem http://api.example.test:8081/status.txt
kill $(jobs -p)
